"use strict";
const QUIZ = {"rank":10,"slug":"ancient-craft","theme":"workshop","atlas":"journey","tile":2,"title":"你的古代天赋技能","setting":"临时进城，凭本事领一块木牌","category":"古代天赋","intro":"你刚进一座虚构的古城，照常做买卖、打听路、搭夜棚。把存活攻略交给你的本能，领回一块写着擅长工种的木牌。","dimensions":["巧作","听写","走访","统筹"],"sections":["清早进城","市集开张","茶棚的一席","货栈和调度","晚灯将尽"],"resultTitle":"你的古城技能牌","action":"进城领工","details":["你常使的本事","城里的人为何来找你","你今天接的小活"],"profiles":[{"name":"灯骨巧匠","identity":"巧作专长","quote":"别人瞧见一截竹，你已经在想灯会亮成什么样。","reason":"你善于用眼和手完成小而准确的改动。遇到做坏的器物，你常常愿意重看材料能做什么。","strength":"他们会带来裂口、松动和打不开的扣子。你留下的修补总有可继续使用的余地。","extra":"替城门口的馄饨铺修好一只晃的灯。报酬是一碗小馄饨，外加给你留到打烊的两只。"},{"name":"茶棚记事人","identity":"听写专长","quote":"一壶茶还没续上，你已经听出了话里第三段故事。","reason":"你擅长把散漫的口头消息整理成有来有往的记录，也能听懂说话人为何犹疑。","strength":"有人来请你代写信，有人只是想讲完一段。他们认可的是你能把口头绕远的事写得清楚。","extra":"帮一位隔壁城的客人代写回信，写完先念给他听，问最后一句可愿意多留一行。"},{"name":"城门脚程客","identity":"走访专长","quote":"你认得路，还知道走到哪儿该先问一句。","reason":"了解一处地点在你看来要靠走动、用眼看和听不同的人说。你愿意从实地找到关键消息。","strength":"摊主缺一筐货、旅人不认岔路，都乐于来求你的随手线索。","extra":"替卖席子的人找到绕开积水的路线。顺路遇见一处新棚子，回程已经记在脑子里。"},{"name":"市集掌筹","identity":"统筹专长","quote":"人群散了再聚，你还是认得谁手里的事没结。","reason":"你能以看得见的方式盘清货、人、时间和位置。安排复杂时，你不容易漏掉正在等的人。","strength":"有人临时找不到摊位，或货和脚夫人数合不上，很容易想到来问你。","extra":"明日市集各家托你写一个简要时辰表。你给晚到的人也留了一格摊位。"},{"name":"纸灯题匠","identity":"巧作与听写","quote":"一封信可以装进灯里，灯便能替人亮一夜。","reason":"你做东西时也想到它怎样讲一个故事。器物上的比例、纹样和留字的位置都可能被你重新排妥。","strength":"你能把别人说不清的意思变成摸得见的物件，使它更值得递给对方。","extra":"做一盏小灯挂在渡口，给夜归的人留四个自己会认出的字。"},{"name":"行路问闻人","identity":"听写与走访","quote":"风一转向，人都知道你会回来讲得清。","reason":"你愿意走一段路去核对听来的故事，并把事实和人的感受各自带回来。","strength":"隔岸消息扑朔迷离时，别人会考虑请你绕两处问一问，再复述给没去过的人。","extra":"茶棚托你去问今天谁最先看见涨水。回来请三个人确认自己说过的那句。"},{"name":"巷路安排师","identity":"走访与统筹","quote":"你去过每个巷口，所以知道拥挤时该留哪条路。","reason":"你了解实际地形和人的使用习惯，安排起来格外顺手。你的计划往往在脚下先走过一遍。","strength":"开夜市、排货车或赶集归来，人们会先问你哪一点最容易堵。","extra":"去上游看一下封了哪段桥，然后写三条小队当天都到得了的路线。"},{"name":"器作管事","identity":"统筹与巧作","quote":"又能看见一颗歪钉子，又能看见后面排的十双手。","reason":"你能把细致的手艺和一群人的时间对在一起。做出好用东西的同时，也知道怎样保持下一次品质。","strength":"需要做十件差不多好的物件时，伙伴最喜欢现在就叫你来安排。","extra":"花一上午带两位新人学会打小小的纸框。忙完时得了一把贴手的旧刻刀当谢礼。"}],"questions":[{"prompt":"城门旁摆着一块刚淋湿的招牌，你最先注意？","options":[{"dimension":0,"text":"哪条木片翘了，补得住吗"},{"dimension":1,"text":"上头那行快洇没的字"},{"dimension":2,"text":"绕着它往哪个路口走比较干"},{"dimension":3,"text":"进出两拨人能不能别挤一块"}]},{"prompt":"有人让你帮忙辨认入城给的木牌。","options":[{"dimension":1,"text":"慢慢辨清文字，补记历史"},{"dimension":2,"text":"问已经从另一扇门进城的人"},{"dimension":3,"text":"按标记发给负责带队的人"},{"dimension":0,"text":"摸牌面刻痕和缺口"}]},{"prompt":"第一次进这座城，哪项物品最想先领？","options":[{"dimension":2,"text":"一条耐磨能走长路的绑腿"},{"dimension":3,"text":"一枚能分配仓位的数筹"},{"dimension":0,"text":"一把能修理小东西的旧刮刀"},{"dimension":1,"text":"一册可写人名地点的白纸"}]},{"prompt":"刚进街就有三个人把事托给你。","options":[{"dimension":3,"text":"归类，问可否先同一趟处理两件"},{"dimension":0,"text":"先修能马上复原的那件东西"},{"dimension":1,"text":"记清每个人托付的原话"},{"dimension":2,"text":"沿路先弄清最远那处在哪"}]},{"prompt":"你发现进城排队的人都借不到水瓢。","options":[{"dimension":1,"text":"问清是谁在最早提到缺水"},{"dimension":0,"text":"拿旧竹片改一个临时瓢"},{"dimension":3,"text":"安排几个人分拨去取，轮流用"},{"dimension":2,"text":"沿旁边街看其他水井开了没有"}]},{"prompt":"摊主问你拿什么抵一夜住处。","options":[{"dimension":2,"text":"替他走一趟远些的送货路线"},{"dimension":1,"text":"写一张给远方亲人的信"},{"dimension":0,"text":"帮忙修几扇漏风的窗"},{"dimension":3,"text":"代管夜里来住客人的次序"}]},{"prompt":"有人交你一包主人没写清的东西。","options":[{"dimension":3,"text":"按抵达时间和认领情况留档"},{"dimension":2,"text":"去两处可能的门牌分别问问"},{"dimension":1,"text":"完整抄下剩余的字迹给人辨认"},{"dimension":0,"text":"拆开外包检查它如何装得稳"}]},{"prompt":"城内第一条街上，往哪儿走会让你最开心？","options":[{"dimension":0,"text":"有不同材质小物件的作坊"},{"dimension":3,"text":"能看见整条街如何开市的高处"},{"dimension":2,"text":"能通向三个不一样的路口"},{"dimension":1,"text":"很多故事传过来的茶桌"}]},{"prompt":"买来的布料受潮，一角几乎不能用。","options":[{"dimension":2,"text":"找来住在前一站的人问哪里淋了雨"},{"dimension":3,"text":"按完好尺寸重新配给要做的几批货"},{"dimension":0,"text":"改成合适尺寸的小荷包"},{"dimension":1,"text":"写清损耗和责任，免得回头说不明白"}]},{"prompt":"摆摊前老板随口说缺一个帮手。","options":[{"dimension":3,"text":"把打包、收钱和补货分给不同人"},{"dimension":0,"text":"做一块可快速装卸的台面"},{"dimension":1,"text":"给买主写一张清楚的商品便签"},{"dimension":2,"text":"去对街留意哪里最适合引来人"}]},{"prompt":"小孩在市集里找不到大人，手里攥一小样东西。","options":[{"dimension":0,"text":"看看物件有什么手工印迹"},{"dimension":1,"text":"问小孩大人最后说的话"},{"dimension":2,"text":"沿刚才走的方向分段问摊主"},{"dimension":3,"text":"请周围人留出空位等家长回来找"}]},{"prompt":"集市有一家很想靠近的摊，你猜是什么？","options":[{"dimension":1,"text":"代写信，还能听各地换来的故事"},{"dimension":2,"text":"说很多河道和山口的新路线"},{"dimension":3,"text":"记得不同摊位与来货点的货行"},{"dimension":0,"text":"展示别人没见过的嵌木技法"}]},{"prompt":"四个摊位想合做一个招牌。","options":[{"dimension":3,"text":"定出落款次序和安装时机"},{"dimension":2,"text":"看看市面上最容易让人看见的位置"},{"dimension":1,"text":"帮他们互相转述想写的意思"},{"dimension":0,"text":"做一块框可以换掉局部"}]},{"prompt":"喝水时发现木勺裂了一道细纹。","options":[{"dimension":0,"text":"趁现在找一小片木料补进去"},{"dimension":3,"text":"把裂瓢和备用瓢分开摆，点一遍数量"},{"dimension":2,"text":"问摊上有人是否知道哪能换新"},{"dimension":1,"text":"提醒管理瓢的人，写上有裂以免误用"}]},{"prompt":"桥边出现没摆过摊的人，大家还不确定能不能合作。","options":[{"dimension":1,"text":"先听清所求的合作是什么"},{"dimension":0,"text":"看看他用的货架牢不牢"},{"dimension":3,"text":"理好一天试卖允许占的位置和时间"},{"dimension":2,"text":"看看他来路与东西平常从哪卖出"}]},{"prompt":"日头高了，下一个最想做的活是哪件？","options":[{"dimension":2,"text":"沿新开的路帮摊主送两件货"},{"dimension":1,"text":"替远来的客商写几句话"},{"dimension":0,"text":"修一张有点摇的摆货桌"},{"dimension":3,"text":"让中午收摊、补货与排队一起运转"}]},{"prompt":"客人把三个版本的消息都塞进同一句话。","options":[{"dimension":0,"text":"拿可擦木板做个比例图"},{"dimension":1,"text":"请他慢慢说，再照原意复述给他"},{"dimension":2,"text":"找两个在场的人逐个问发生地点"},{"dimension":3,"text":"把跟眼下处理有关的事先列次序"}]},{"prompt":"你抬头时，茶棚角落正在准备演一出小戏。","options":[{"dimension":1,"text":"注意第一个人如何讲故事"},{"dimension":2,"text":"沿着散场的人听几个不同反应"},{"dimension":3,"text":"把倒茶和引坐的位置空出来"},{"dimension":0,"text":"看看那块可拆卸的戏台怎么搭"}]},{"prompt":"老人为儿孙带了一小包点心，苦于写不进信里。","options":[{"dimension":2,"text":"找下一班走同方向的人"},{"dimension":3,"text":"确认信与包裹的交接日期及地点"},{"dimension":0,"text":"用自己折的方法把温热留住"},{"dimension":1,"text":"问他最想让家里人知道哪句话"}]},{"prompt":"好几家摊位都说听到了新规，版本互不相同。","options":[{"dimension":3,"text":"先把照旧可办的事安排妥当"},{"dimension":0,"text":"做一面不怕雨的小板写清消息"},{"dimension":1,"text":"将诸说都抄整齐，再问哪条有依据"},{"dimension":2,"text":"到两个说消息最早的地方核对"}]},{"prompt":"有人想讲道街西的故事，大家以为什么都记得。","options":[{"dimension":1,"text":"听两遍，留住当事人改口的地方"},{"dimension":0,"text":"做件能拿在手里的小示意物"},{"dimension":3,"text":"约涉及的人改天按时间一起来说"},{"dimension":2,"text":"趁天亮亲自走到街西看看"}]},{"prompt":"两个最熟的邻居因为口头信息误解了彼此。","options":[{"dimension":2,"text":"去问恰好经过听过的伙计"},{"dimension":1,"text":"让两人分别说清谁说过什么"},{"dimension":0,"text":"指出他们对同一件器物的不同叫法"},{"dimension":3,"text":"提出后续口头交代和核对的办法"}]},{"prompt":"客人离开后留下一只绣了图案的布袋。","options":[{"dimension":3,"text":"把失物清点入册，统一由柜台认领"},{"dimension":2,"text":"沿他离开时走的巷子找过去"},{"dimension":1,"text":"记下他用过的称呼和落座的话"},{"dimension":0,"text":"看看缝线能否认出制作人"}]},{"prompt":"茶棚的老板喜欢请你做哪件小事最符合你？","options":[{"dimension":0,"text":"修一把泡胀了的木凳"},{"dimension":3,"text":"安排十几张凳子都有人坐好"},{"dimension":2,"text":"跑几条不同的路送信"},{"dimension":1,"text":"代写两封语气不同的请帖"}]},{"prompt":"一车货在进栈前出了点风波。","options":[{"dimension":2,"text":"去对照车经过的湿痕和交接点"},{"dimension":3,"text":"叫人先让出门口，然后按清单验货"},{"dimension":0,"text":"检查箱角固定的小钉"},{"dimension":1,"text":"把各人的说法按时序写出来"}]},{"prompt":"有人忘了告诉另一个人把空筐拿回来。","options":[{"dimension":3,"text":"修改来回登记，给晚到筐留个位置"},{"dimension":0,"text":"先补做几个临时可用的框架"},{"dimension":1,"text":"把容易漏说的词标给伙计看"},{"dimension":2,"text":"跑到下一站询问哪处还有空筐"}]},{"prompt":"货栈准备给新邻居发打包物资。","options":[{"dimension":0,"text":"挑容易重新拆装的盒子"},{"dimension":1,"text":"给每一类写一句明白的说明"},{"dimension":2,"text":"先走一遍容易卡车的路"},{"dimension":3,"text":"确认人数、份数和最后到达时辰"}]},{"prompt":"城里忽然来了许多借住的人。","options":[{"dimension":1,"text":"记得清入住人的称呼、来由与需要"},{"dimension":2,"text":"找到附近几处尚可借住的地方"},{"dimension":3,"text":"按家庭和时长重新排夜间房间"},{"dimension":0,"text":"把坏掉的床板和桌腿先修好"}]},{"prompt":"你想给容易混的两类货作标记。","options":[{"dimension":3,"text":"用不同栈位和装车顺序区分"},{"dimension":2,"text":"根据不同来历问清两条原路线"},{"dimension":1,"text":"选两个字写得让人一眼辨清"},{"dimension":0,"text":"在盖子角做两种拿手的记号"}]},{"prompt":"同行里有人累了想换下手里的活。","options":[{"dimension":0,"text":"挑一件坐着也能做的修补活"},{"dimension":3,"text":"把同时段的工作按能否延后重排"},{"dimension":2,"text":"带他走最短的路线去安静处"},{"dimension":1,"text":"听他是身上哪里累，顺手记一下"}]},{"prompt":"一场小雨让原先的堆货办法用不上了。","options":[{"dimension":1,"text":"标出需要当面交接的几件"},{"dimension":0,"text":"用简单框架把怕湿的东西先垫高"},{"dimension":3,"text":"找干角落重排搬运顺序"},{"dimension":2,"text":"去前街问借得出空屋的是哪一家"}]},{"prompt":"明日要把同样数量的货送去三个地方。","options":[{"dimension":2,"text":"提前辨出三条全能到的路线"},{"dimension":1,"text":"写清每批货的收件说法"},{"dimension":0,"text":"换更省材料的打包方法"},{"dimension":3,"text":"给三批车排合理的发出间隔"}]},{"prompt":"快打烊了，你打算把一件小贡献留在哪儿？","options":[{"dimension":0,"text":"亲手做好的器物留在摊前"},{"dimension":1,"text":"当天听到的事整理成给自己看的册子"},{"dimension":2,"text":"记下一条让晚归人少走冤枉路的线"},{"dimension":3,"text":"把明早的开门人员和时段写在柱上"}]},{"prompt":"掌柜邀你下一回还来，你最想收下什么谢礼？","options":[{"dimension":1,"text":"一叠手感好的纸和细笔"},{"dimension":2,"text":"告诉我一条外地人少知道的路线"},{"dimension":3,"text":"一张能直接带我进仓看流程的通行牌"},{"dimension":0,"text":"一把用得惯的旧工具"}]},{"prompt":"城将在半个时辰后关门，你需要帮四个人办妥最后一件事。","options":[{"dimension":2,"text":"挑一条最快最安全的可走路把人领过去"},{"dimension":3,"text":"给大家排序，确认没有人被遗漏"},{"dimension":0,"text":"把脱落的物件固定到能正常带走"},{"dimension":1,"text":"把写给城外亲友的短笺校对好"}]},{"prompt":"明日醒来想换个新本事练习。","options":[{"dimension":3,"text":"试着让陌生伙伴陪你做完一次摊务"},{"dimension":0,"text":"把简陋材料改成耐用器具"},{"dimension":1,"text":"记一段亲历者怎样书写那天的事"},{"dimension":2,"text":"走过一个以前只听说的关口"}]},{"prompt":"有人带你去看一家真正信赖你的铺子，门前挂着什么？","options":[{"dimension":1,"text":"愿意跟你讲故事的茶牌"},{"dimension":0,"text":"用过很多次还牢固的竹作"},{"dimension":3,"text":"谁都能看明白的取货次序"},{"dimension":2,"text":"标出方向和绕路的旧地图"}]},{"prompt":"今天跟你共事的人想为你起绰号。","options":[{"dimension":2,"text":"「跑过之后才说这儿能走」"},{"dimension":1,"text":"「一句话听两遍就记得」"},{"dimension":0,"text":"「手指摸一次就知道怎么修」"},{"dimension":3,"text":"「每件事都晓得归到哪儿去」"}]},{"prompt":"夜晚只剩下几盏灯亮着，你最放不下哪件事？","options":[{"dimension":3,"text":"睡前有个工序还没交代清楚"},{"dimension":2,"text":"城西那条恰好有灯的路还没跑过"},{"dimension":1,"text":"今天有一个人没说完他的故事"},{"dimension":0,"text":"有一处不太合手的小件还能修好"}]},{"prompt":"守夜人问你这城下一次开放想帮什么？","options":[{"dimension":0,"text":"修一些人们天天会用的东西"},{"dimension":3,"text":"让那么多人出门回家时都有点秩序"},{"dimension":2,"text":"带新来的人走几条可靠的路"},{"dimension":1,"text":"在茶棚听完几段值得留下的话"}]}],"art":"data:image/jpeg;base64,"};
